using System.Security.Cryptography;

var data = new byte[200_000_000];
Task<string> export = ExportAsync(data);
Console.WriteLine("Back in the caller"); // printed only after the hashing
await export;

static async Task<string> ExportAsync(byte[] data)
{
    // async moved nothing: this runs on the caller's thread
    string hash = Convert.ToHexString(SHA256.HashData(data));
    await File.WriteAllTextAsync("export.sha256", hash); // first await
    return hash;
}

using System.Security.Cryptography;

var data = new byte[200_000_000];
Task<string> export = ExportAsync(data);
Console.WriteLine("Back in the caller"); // printed right away
await export;

static async Task<string> ExportAsync(byte[] data)
{
    // CPU-bound work: ask the thread pool for a thread explicitly
    string hash = await Task.Run(
        () => Convert.ToHexString(SHA256.HashData(data)));
    await File.WriteAllTextAsync("export.sha256", hash);
    return hash;
}
